import React from 'react'
import './footer.css';
import { Container, Row, Col, ListGroup, ListGroupItem } from 'reactstrap';
import { Link } from 'react-router-dom';
import logo from '../../assets/images/logo.png';


const quick__links = [
    {
        path: '/home',
        display: 'Home'
    },
    {
        path: '/about',
        display: 'About'
    },
    {
        path: '/tours',
        display: 'Tours'
    }

];
const quick__links2 = [
    {
        path: '/gallery',
        display: 'Gallery'
    },
    {
        path: '/login',
        display: 'Login'
    },
    {
        path: '/register',
        display: 'Register'
    }

];
// const quick__links3 = [
//     {
//         path: '/admin',
//         display: 'Admin'
//     },
//     {
//         path: '/login',
//         display: 'Admin-Login'
//     },
//     {
//         path: '/register',
//         display: 'Admin-Register'
//     }

// ];



function Footer() {

    const year = new Date().getFullYear();
    return (
        <footer className='footer'>
            <Container>
                <Row>
                    <Col lg='3'>
                        <div className='logo'>
                            <img src={logo} alt='' />
                            <p>Find unique adventures and unforgettable journeys tailored for nomads.</p>

                            <div className='social__links d-flex align-items-center gap-4'>

                                <span>
                                    <Link to="#">
                                        <i className="ri-youtube-line"></i>
                                    </Link>
                                </span>
                                <span>
                                    <Link to="#">
                                        <i className="ri-github-fill"></i>
                                    </Link>
                                </span>
                                <span>
                                    <Link to="#">
                                        <i className="ri-facebook-circle-line"></i>
                                    </Link>
                                </span>
                                <span>
                                    <Link to="#">
                                        <i className="ri-youtube-line"></i>
                                    </Link>
                                </span>


                            </div>
                        </div>

                    </Col>
                    <Col lg='3'>
                        <h5 className='footer__links-title'>Discover</h5>
                        <ListGroup className="footer__quick-links">
                            {
                                quick__links.map((item, index) => (
                                    <ListGroupItem key={index} className="ps-0 border-0">
                                        <Link to={item.path}>{item.display}</Link>
                                    </ListGroupItem>
                                ))
                            }
                        </ListGroup>
                    </Col>
                    <Col lg='3'>
                        <h5 className='footer__links-title'>Quick Links</h5>
                        <ListGroup className="footer__quick-links">
                            {
                                quick__links2.map((item, index) => (
                                    <ListGroupItem key={index} className="ps-0 border-0">
                                        <Link to={item.path}>{item.display}</Link>
                                    </ListGroupItem>
                                ))
                            }
                        </ListGroup>
                    </Col>
                    {/* <Col lg='2'>
                        <h5 className='footer__links-title'>Admin Links</h5>

                        <ListGroup className="footer__quick-links">
                            {

                                quick__links3.map((item, index) => (
                                    <ListGroupItem key={index} className="ps-0 border-0">
                                        <Link to={item.path}>{item.display}</Link>
                                    </ListGroupItem>
                                ))
                            }
                        </ListGroup>
                    </Col> */}

                    <Col lg='3'>
                        <h5 className='footer__links-title'>Contacts</h5>
                        <ListGroup className="footer__quick-links">


                            <ListGroupItem className="ps-0 border-0 d-flex align-items-center gap-3">
                                <h6 className='mb-0 d-flex align-items-center gap-2'>
                                    <span><i class='ri-map-pin-line'></i></span>
                                    Address:
                                </h6>
                                <p className='mb-0'>Delhi,India</p>
                            </ListGroupItem>

                            <ListGroupItem className="ps-0 border-0 d-flex align-items-center gap-3">
                                <h6 className='mb-0 d-flex align-items-center gap-2'>
                                    <span>
                                        <i class='ri-mail-line'></i>
                                    </span>
                                    Email:
                                </h6>
                                <p className='mb-0'>punjbhai@gmail.com</p>
                            </ListGroupItem>

                            <ListGroupItem className="ps-0 border-0 d-flex align-items-center gap-3">
                                <h6 className='mb-0 d-flex align-items-center gap-2'>
                                    <span><i class='ri-phone-fill'></i></span>
                                    Phone:
                                </h6>
                                <p className='mb-0'>+91-987654321123</p>
                            </ListGroupItem>
                        </ListGroup>
                    </Col>
                    <Col lg='12' className='text-center pt-5'>
                        <p className="copyright">
                            Copyright {year} ,design and develop by punj, All rights reserved.
                        </p>

                    </Col>
                </Row>
            </Container>
        </footer>
    )
}

export default Footer
